export default class Detail extends BaseController {
  private timer?: number;

  // 1. once - controls created, NOT yet in the DOM
  public onInit(): void {
    this.getView().setModel(new JSONModel({ busy: false, editMode: false }), "view");
    this.getRouter().getRoute("detail").attachPatternMatched(this.onRouteMatched, this);
    this.getOwnerComponent().getEventBus().subscribe("app", "refresh", this.onRefresh, this);
  }

  // 2. before every rendering
  public onBeforeRendering(): void { }

  // 3. after every rendering - the DOM is available
  public onAfterRendering(): void {
    // for example attach a third-party chart to this.byId("chartBox").getDomRef()
  }

  // 4. once - the view is destroyed
  public onExit(): void {
    this.getOwnerComponent().getEventBus().unsubscribe("app", "refresh", this.onRefresh, this);
    window.clearInterval(this.timer);
  }
}

