import Controller from "sap/ui/core/mvc/Controller";
import UIComponent from "sap/ui/core/UIComponent";
import Router from "sap/ui/core/routing/Router";
import History from "sap/ui/core/routing/History";
import Model from "sap/ui/model/Model";
import ResourceModel from "sap/ui/model/resource/ResourceModel";
import ResourceBundle from "sap/base/i18n/ResourceBundle";

/**
 * @namespace my.app.controller
 */
export default abstract class BaseController extends Controller {
  public getRouter(): Router {
    return (this.getOwnerComponent() as UIComponent).getRouter();
  }

  public getModel(name?: string): Model {
    return this.getView().getModel(name);
  }

  public getText(key: string, args?: string[]): string {
    const bundle = (this.getOwnerComponent().getModel("i18n") as ResourceModel).getResourceBundle() as ResourceBundle;
    return bundle.getText(key, args);
  }

  public onNavBack(): void {
    if (History.getInstance().getPreviousHash() !== undefined) {
      window.history.go(-1);
    } else {
      this.getRouter().navTo("main", {}, true);   // true = replace, no new history entry
    }
  }
}

// A child controller
export default class Detail extends BaseController {
  public onInit(): void {
    super.onInit?.();      // run the parent's setup first (if it has one)
    this.getRouter().getRoute("detail").attachPatternMatched(this.onObjectMatched, this);
  }
}

