import ManagedObject from "sap/ui/base/ManagedObject";
import Fragment from "sap/ui/core/Fragment";
import Dialog from "sap/m/Dialog";
import JSONModel from "sap/ui/model/json/JSONModel";
import View from "sap/ui/core/mvc/View";

/**
 * @namespace my.app.controller
 */
export default class CreateProductDialog extends ManagedObject {
  private dialog?: Dialog;
  private resolveFn?: (data: object | null) => void;

  constructor(private view: View) {
    super();
  }

  public async open(): Promise<object | null> {
    if (!this.dialog) {
      this.dialog = await Fragment.load({
        id: this.view.getId(),
        name: "my.app.view.fragment.CreateProduct",
        controller: this                       // the fragment's handlers live in THIS class
      }) as Dialog;
      this.view.addDependent(this.dialog);     // view models + destroyed with the view
    }
    this.dialog.setModel(new JSONModel({ name: "", price: 0 }), "new");
    this.dialog.open();
    return new Promise((resolve) => { this.resolveFn = resolve; });
  }

  public onSave(): void {
    const data = (this.dialog.getModel("new") as JSONModel).getData();
    this.dialog.close();
    this.resolveFn(data);
  }

  public onCancel(): void {
    this.dialog.close();
    this.resolveFn(null);
  }
}

